import{_ as o,o as t,c,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"FR 3.8.2 — Disconnect Account","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/07-publishing-social/3-8-2-disconnect-account/spec.md","filePath":"feature/srs/07-publishing-social/3-8-2-disconnect-account/spec.md"}'),a={name:"feature/srs/07-publishing-social/3-8-2-disconnect-account/spec.md"};function s(i,e,r,d,l,u){return t(),c("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-8-2-—-disconnect-account" tabindex="-1">FR 3.8.2 — Disconnect Account <a class="header-anchor" href="#fr-3-8-2-—-disconnect-account" aria-label="Permalink to &quot;FR 3.8.2 — Disconnect Account&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.8.2</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-108</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Disconnect Account</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Publishing &amp; Social (<code>3.8</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Client</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-52, BR-54</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG03, MSG07, MSG43</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Allow authorized <code>Owner</code>, <code>Manager</code>, and <code>Client</code> members of a Workspace to safely disconnect a linked Facebook, Instagram, TikTok, or Threads account, revoking upstream OAuth grants best-effort, purging encrypted token material in MongoDB <code>social_accounts</code>, and preventing orphaned scheduled publish jobs while preserving historical <code>PUBLISHED</code> post records.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized member holding <code>Owner, Manager, Client</code> in a Workspace, I want to execute <strong>Disconnect Account</strong> reliably across BrandHub&#39;s supported social publishing pipeline (<strong>Facebook, Instagram, TikTok, Threads</strong>) so that approved brand content is delivered, previewed, scheduled, and audited safely with full tenant isolation (<code>BR-20, BR-52, BR-54</code>).</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Workspace Scope (<code>BR-20</code>):</strong> Only authenticated Workspace members with role in <code>Owner, Manager, Client</code> may invoke the public REST endpoints for <code>Disconnect Account</code>; unauthorized roles or cross-workspace requests fail deterministically with <code>403 FORBIDDEN</code> (<code>MSG07</code>).</li><li><strong>Four-Platform Scope Discipline:</strong> Strictly supports <strong>Facebook</strong>, <strong>Instagram</strong>, <strong>TikTok</strong>, and <strong>Threads</strong> — legacy/de-scoped platforms (such as Zalo OA or LinkedIn) are rejected at validation boundaries (<code>MSG02</code>).</li><li><strong>Production Pipeline &amp; Idempotency:</strong></li></ol><ul><li><strong>1. Workspace Ownership &amp; Role Verification:</strong> Verifies caller holds <code>Owner</code>, <code>Manager</code>, or <code>Client</code> in the Workspace owning <code>SocialAccountDocument</code> <code>{id}</code> (<code>Creator</code> is rejected with <code>403 FORBIDDEN</code>).</li><li><strong>2. Scheduled Post Guard (<code>BR-54</code>):</strong> Checks MongoDB <code>posts</code> for <code>SCHEDULED</code> or <code>PUBLISHING</code> entries targeting <code>{id}</code>. Active <code>PUBLISHING</code> jobs block immediate disconnect (<code>409 CONFLICT</code>) or require confirmation; future <code>SCHEDULED</code> targets on that account transition to <code>PAUSED_ACCOUNT_DISCONNECTED</code> so <code>PublishJobConsumer</code> never dispatches wiped credentials.</li><li><strong>3. Upstream Revocation &amp; Token Wipe:</strong> Calls <code>publisher-service</code> <code>/api/v1/social/tokens/revoke</code> with bounded timeout; regardless of upstream provider HTTP error (e.g. already revoked externally), clears <code>encryptedAccessToken</code> / <code>encryptedRefreshToken</code>, sets <code>status = DISCONNECTED</code> and <code>disconnectedAt = now()</code>, and preserves <code>platformAccountId</code> + display metadata for past <code>PUBLISHED</code> post detail views (FR 3.8.4).</li></ul><ol start="4"><li><strong>Token &amp; Credential Security:</strong> Raw OAuth access/refresh tokens are encrypted at rest via AES-256-GCM (<code>CryptoUtils</code>) and never returned in client-facing <code>ApiResponse&lt;T&gt;</code> DTOs or written to application logs.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All buttons, platform badges, status pills, validation alerts, and modal copy use synchronized key-parallel entries (<code>connections.disconnect.title</code>, <code>connections.disconnect.scheduledWarning</code>, <code>connections.disconnect.confirm</code>, <code>connections.status.disconnected</code> in <code>vi.json</code> &amp; <code>en.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces (<code>pages/connections/index.tsx</code> (Disconnect confirmation modal with scheduled-post impact count), <code>pages/client/components/ClientSocialAccounts.tsx</code> on Web and <code>src/screens/more/SocialAccountsScreen.tsx</code> (destructive confirmation dialog), <code>src/services/socialAccountService.ts</code> on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/connections/index.tsx</code> (Disconnect confirmation modal with scheduled-post impact count), <code>pages/client/components/ClientSocialAccounts.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/more/SocialAccountsScreen.tsx</code> (destructive confirmation dialog), <code>src/services/socialAccountService.ts</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / In-Flight:</strong> Skeleton placeholders on read views; spinner + disabled action button on mutations to prevent duplicate submissions.</li><li><strong>Empty:</strong> Contextual guidance card (e.g., prompt to connect social account via FR 3.8.1 or create/schedule a post via FR 3.8.6) with localized CTA.</li><li><strong>Success:</strong> Immediate <code>TanStack Query</code> cache invalidation, live status badge update, and localized toast notification.</li><li><strong>Error / Retryable Failure:</strong> Structured inline banner displaying localized error reason mapped from <code>MSG01, MSG03, MSG07, MSG43</code> without losing draft edits.</li></ul></li></ul><h2 id="_5-api-messaging-contract" tabindex="-1">5. API &amp; Messaging Contract <a class="header-anchor" href="#_5-api-messaging-contract" aria-label="Permalink to &quot;5. API &amp; Messaging Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Endpoint / Upstream Route</th><th style="text-align:left;">Auth / Security</th><th style="text-align:left;">Controller / Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>DELETE /api/v1/social-accounts/{id}?workspaceId={workspaceId}</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Client</code>)</td><td style="text-align:left;"><code>SocialAccountController.disconnect()</code> (<code>business-service</code>) -&gt; validates Workspace scope, revokes token, marks <code>DISCONNECTED</code></td></tr><tr><td style="text-align:left;"><code>POST /api/v1/social/tokens/revoke</code></td><td style="text-align:left;"><code>X-Internal-Service-Key</code></td><td style="text-align:left;"><code>SocialOAuthController.revokeToken()</code> (<code>publisher-service</code>) -&gt; calls Meta/TikTok/Threads token revocation endpoint best-effort</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>SOCIAL_ACCOUNT_NOT_FOUND</code> (<code>404</code>, <code>MSG01</code>): Account ID does not exist or belongs to another Workspace.</li><li><code>POST_CURRENTLY_PUBLISHING</code> (<code>409</code>, <code>MSG43</code>): A publish job for this account currently holds Redis lock <code>processingPostIds:{postId}:{platform}</code>.</li><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): <code>Creator</code> or cross-workspace actor attempts to disconnect account.</li><li><strong>Duplicate Delivery / Network Retry:</strong> <code>PublishJobConsumer</code> enforces Redis lock <code>processingPostIds:{postId}:{platform}</code> (<code>30m</code> TTL) and <code>DefaultClassMapper</code> cross-service <code>PublishJobMessage</code> compatibility so broker redeliveries never double-post to a Client&#39;s live social feed.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Domain Index &amp; Sibling FRs:</strong> <a href="./../README.html">3.8 Publishing &amp; Social Index</a> · <a href="./../3-8-1-connect-social-account/spec.html">FR 3.8.1 — Connect Social Account</a> · <a href="./../3-8-7-track-post-status/spec.html">FR 3.8.7 — Track Post Status</a></li><li><strong>Consolidated Extension Module:</strong> <a href="./../../../modules/07-billing-publisher-and-observability/social-publisher-resilience/spec.html"><code>social-publisher-resilience</code></a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/07-publishing-social.html">BA 3.8 Publishing &amp; Social</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified across <code>brandhub-business-service</code> and <code>brandhub-publisher-service</code> JUnit suites, RabbitMQ + Redis lock integration checks, Web &amp; Mobile UI integration, <code>vi.json</code>/<code>en.json</code> parity, and Light/Dark mode verification (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped platforms (Zalo OA), livestream broadcasting, or automated paid ad-spend boosting.</li></ul>',21)])])}const h=o(a,[["render",s]]);export{g as __pageData,h as default};
